import Link from "next/link";
import type { ReactNode } from "react";

import type { SwarmTarget } from "../_lib/config-types";
import { cap, formatNumber, formatPercent, word } from "../_lib/format";
import type { TargetSummary } from "../_lib/queries";
import { swarmConfig } from "../swarm.config";
import { ArrowIcon, TargetMark, targetStyle } from "./icons";

/**
 * The page bands of the overview: a hero, full-width sections with large
 * headings, target cards and numbered steps. Every word comes from
 * swarm.config.ts or from memory.
 */

/** A text link with a trailing arrow, for "next" actions. */
export function NextLink({ href, children, out }: { href: string; children: ReactNode; out?: boolean }) {
  return (
    <Link className="rp-next" href={href}>
      {children}
      <ArrowIcon out={out} />
    </Link>
  );
}

export function Hero({
  note,
  title,
  lede,
  actions,
  backdrop = true,
}: {
  /** A quiet line under the lede, e.g. how the goal is measured. */
  note?: ReactNode;
  title: string;
  lede?: ReactNode;
  actions?: ReactNode;
  backdrop?: boolean;
}) {
  return (
    <header className="rp-hero">
      {backdrop ? <HeroBackdrop targets={swarmConfig.targets} /> : null}
      <div className="rp-hero-inner">
        <h1>{title}</h1>
        {lede ? <p className="rp-hero-lede">{lede}</p> : null}
        {note ? <p className="rp-hero-note">{note}</p> : null}
        {actions ? <div className="rp-actions">{actions}</div> : null}
      </div>
    </header>
  );
}

/**
 * Receding planes, one per target (up to three), tinted with the target's
 * colour. Decorative only.
 */
function HeroBackdrop({ targets }: { targets: SwarmTarget[] }) {
  const planes = (targets.length > 0 ? targets : [{ id: "_", name: "", color: "var(--rp-ink-soft)", description: "" }]).slice(0, 3);
  return (
    <div aria-hidden="true" className="rp-hero-backdrop">
      {planes.map((target, index) => (
        <span className={`rp-plane rp-plane-${index + 1}`} key={target.id} style={targetStyle(target)} />
      ))}
    </div>
  );
}

/** A full-width band with a large heading. `tone` alternates the ground. */
export function Band({
  title,
  lede,
  id,
  tone,
  action,
  children,
}: {
  title: string;
  lede?: ReactNode;
  id?: string;
  tone?: "sunk";
  action?: ReactNode;
  children: ReactNode;
}) {
  const headingId = id ?? `b-${title.toLowerCase().replace(/[^a-z0-9]+/g, "-")}`;
  return (
    <section aria-labelledby={headingId} className={tone === "sunk" ? "rp-band rp-band-sunk" : "rp-band"}>
      <div className="rp-band-inner">
        <h2 className="rp-band-title" id={headingId}>
          {title}
        </h2>
        {lede ? <p className="rp-band-lede">{lede}</p> : null}
        {action ? <p className="rp-band-action">{action}</p> : null}
        {children}
      </div>
    </section>
  );
}

/**
 * One target as a card: its mark and name, the headline figure (the latest
 * score in score mode, versions shipped otherwise), the latest version and a
 * line on what the record says next.
 */
export function TargetCard({ entry, headingLevel = 3 }: { entry: TargetSummary; headingLevel?: 2 | 3 }) {
  const { target, latest } = entry;
  const href = `/swarm/targets/${encodeURIComponent(target.id)}`;
  const score = swarmConfig.measure.mode === "score";
  const Heading = headingLevel === 2 ? "h2" : "h3";
  const headline = score
    ? { label: swarmConfig.measure.label || cap(word("score")), value: formatNumber(latest?.score ?? null), unit: swarmConfig.measure.unit }
    : { label: `${cap(word("versions"))} ${word("shipped")}`, value: formatNumber(entry.versions), unit: "" };

  let next: ReactNode;
  if (entry.results === 0 && entry.versions === 0) {
    next = (
      <>
        Nothing measured yet. The first {word("result")} lands when an {word("agent")} runs{" "}
        <code>npx rallypoint swarm referee --target {target.id}</code>.
      </>
    );
  } else {
    const parts = [`${formatNumber(entry.passed)} of ${formatNumber(entry.results)} ${word(entry.results === 1 ? "result" : "results")} passed`];
    if (entry.buried > 0) parts.push(`${formatNumber(entry.buried)} ${word(entry.buried === 1 ? "idea" : "ideas")} ${word("buried")}`);
    if (entry.delivery && entry.delivery.total > 0) {
      parts.push(`${formatPercent(entry.delivery.merged / entry.delivery.total)} of issues merged`);
    }
    next = `${parts.join(" · ")}.`;
  }

  return (
    <article className="rp-tcard" style={targetStyle(target)}>
      <header className="rp-tcard-head">
        <TargetMark size="l" target={target} />
        <div>
          <Heading className="rp-tcard-name">
            <Link className="rp-cover" href={href}>
              {target.name}
            </Link>
          </Heading>
          {target.description ? <p className="rp-tcard-desc">{target.description}</p> : null}
        </div>
        <ArrowIcon />
      </header>
      <dl className="rp-tcard-figs">
        <div>
          <dt>{headline.label}</dt>
          <dd className="rp-big">
            {headline.value}
            {headline.unit && headline.value !== "—" ? <span className="rp-unit">{headline.unit}</span> : null}
          </dd>
        </div>
        <div>
          <dt>{cap(word("version"))}</dt>
          <dd className="rp-mid">{latest?.version ?? "—"}</dd>
        </div>
      </dl>
      <p className="rp-tcard-next">{next}</p>
    </article>
  );
}

/** Numbered steps, two columns on wide screens. */
export function Steps({ steps }: { steps: { title: string; body: ReactNode }[] }) {
  return (
    <ol className="rp-steps-list">
      {steps.map((step, index) => (
        <li key={step.title}>
          <span aria-hidden="true" className="rp-step-n">
            {String(index + 1).padStart(2, "0")}
          </span>
          <div>
            <h3>{step.title}</h3>
            <p>{step.body}</p>
          </div>
        </li>
      ))}
    </ol>
  );
}

import type { CSSProperties } from "react";

import type { SwarmTarget } from "../_lib/config-types";
import { formatDate, formatNumber, formatScore, formatShortDate } from "../_lib/format";
import type { Delivery } from "../_lib/github";
import type { VersionRow } from "../_lib/types";

/* ───────────────────────── Score step chart (score mode) ───────────────────────── */

type Series = { target: SwarmTarget; marker: number; points: { t: number; score: number; row: VersionRow }[] };

const MARKERS = ["circle", "square", "triangle", "diamond", "bar"] as const;

function Marker({ kind, x, y }: { kind: number; x: number; y: number }) {
  const shape = MARKERS[kind % MARKERS.length];
  if (shape === "circle") return <circle cx={x} cy={y} r={4.5} />;
  if (shape === "square") return <rect height={8} width={8} x={x - 4} y={y - 4} />;
  if (shape === "triangle") return <path d={`M${x} ${y - 5.5}L${x + 5.5} ${y + 4.5}H${x - 5.5}z`} />;
  if (shape === "diamond") return <path d={`M${x} ${y - 6}L${x + 6} ${y}L${x} ${y + 6}L${x - 6} ${y}z`} />;
  return <rect height={10} width={4} x={x - 2} y={y - 5} />;
}

function LegendMarker({ kind }: { kind: number }) {
  return (
    <svg aria-hidden="true" className="rp-legend-marker" height="14" viewBox="0 0 14 14" width="14">
      <Marker kind={kind} x={7} y={7} />
    </svg>
  );
}

function niceTicks(min: number, max: number, count: number): number[] {
  if (min === max) return [min];
  const span = max - min;
  const step0 = span / count;
  const magnitude = 10 ** Math.floor(Math.log10(step0));
  const step = [1, 2, 2.5, 5, 10].map((m) => m * magnitude).find((s) => s >= step0) ?? step0;
  const ticks: number[] = [];
  for (let v = Math.ceil(min / step) * step; v <= max + step * 1e-9; v += step) ticks.push(Number(v.toPrecision(12)));
  return ticks;
}

function Plot({ series, width, height, label }: { series: Series[]; width: number; height: number; label: string }) {
  const pad = { top: 16, right: width < 500 ? 16 : 120, bottom: 32, left: 52 };
  const all = series.flatMap((s) => s.points);
  const now = Date.now();
  const t0 = Math.min(...all.map((p) => p.t));
  const t1 = Math.max(now, ...all.map((p) => p.t));
  let lo = Math.min(...all.map((p) => p.score));
  let hi = Math.max(...all.map((p) => p.score));
  if (lo === hi) {
    lo -= 1;
    hi += 1;
  }
  const yTicks = niceTicks(lo, hi, 4);
  lo = Math.min(lo, yTicks[0] ?? lo);
  hi = Math.max(hi, yTicks[yTicks.length - 1] ?? hi);
  const x = (t: number) => pad.left + ((t - t0) / Math.max(1, t1 - t0)) * (width - pad.left - pad.right);
  const y = (v: number) => pad.top + (1 - (v - lo) / (hi - lo)) * (height - pad.top - pad.bottom);
  const xTicks = [t0, t0 + (t1 - t0) / 2, t1];

  return (
    <svg className="rp-plot" role="img" aria-label={label} viewBox={`0 0 ${width} ${height}`}>
      <g className="rp-plot-grid">
        {yTicks.map((tick) => (
          <g key={tick}>
            <line x1={pad.left} x2={width - pad.right} y1={y(tick)} y2={y(tick)} />
            <text textAnchor="end" x={pad.left - 8} y={y(tick) + 4}>
              {formatNumber(tick)}
            </text>
          </g>
        ))}
        {xTicks.map((tick, index) => (
          <text
            key={tick}
            textAnchor={index === 0 ? "start" : index === xTicks.length - 1 ? "end" : "middle"}
            x={x(tick)}
            y={height - 10}
          >
            {formatShortDate(tick)}
          </text>
        ))}
      </g>
      {series.map((s) => {
        let d = "";
        s.points.forEach((p, index) => {
          d += index === 0 ? `M${x(p.t)} ${y(p.score)}` : `H${x(p.t)}V${y(p.score)}`;
        });
        const last = s.points[s.points.length - 1]!;
        d += `H${x(t1)}`;
        return (
          <g className="rp-plot-series" key={s.target.id} style={{ "--rp-series": s.target.color } as CSSProperties}>
            <path d={d} />
            {s.points.map((p) => (
              <Marker key={p.row.id} kind={s.marker} x={x(p.t)} y={y(p.score)} />
            ))}
            {pad.right > 40 ? (
              <text className="rp-plot-label" x={x(t1) + 8} y={y(last.score) + 4}>
                {s.target.name}
              </text>
            ) : null}
          </g>
        );
      })}
    </svg>
  );
}

/**
 * Shipped versions' scores over time, one step line per target. Each target
 * has its own colour AND marker shape, is named in the legend and at the
 * line's end, and the same data is available as a table.
 */
export function ScoreChart({
  versions,
  targets,
  label,
}: {
  versions: VersionRow[];
  targets: SwarmTarget[];
  label: string;
}) {
  const series: Series[] = targets
    .map((target, index) => ({
      target,
      marker: index,
      points: versions
        .filter((row) => row.target === target.id && typeof row.score === "number")
        .map((row) => ({ t: new Date(row.created_at).getTime(), score: row.score as number, row }))
        .sort((a, b) => a.t - b.t),
    }))
    .filter((s) => s.points.length > 0);
  if (series.length === 0) return null;
  const summary = `${label}: ${series
    .map((s) => `${s.target.name} ${formatScore(s.points[s.points.length - 1]!.score)}`)
    .join(", ")}`;

  return (
    <figure className="rp-chart">
      <ul className="rp-legend">
        {series.map((s) => (
          <li key={s.target.id} style={{ "--rp-series": s.target.color } as CSSProperties}>
            <LegendMarker kind={s.marker} />
            {s.target.name}
          </li>
        ))}
      </ul>
      <div className="rp-plot-wide">
        <Plot height={300} label={summary} series={series} width={760} />
      </div>
      <div className="rp-plot-narrow">
        <Plot height={240} label={summary} series={series} width={360} />
      </div>
      <details className="rp-details">
        <summary>Show the data as a table</summary>
        <div className="rp-scroll">
          <table className="rp-table">
            <thead>
              <tr>
                <th scope="col">Target</th>
                <th scope="col">Version</th>
                <th scope="col">Score</th>
                <th scope="col">When</th>
              </tr>
            </thead>
            <tbody>
              {series.flatMap((s) =>
                s.points.map((p) => (
                  <tr key={p.row.id}>
                    <td>{s.target.name}</td>
                    <td className="rp-mono">{p.row.version}</td>
                    <td>{formatScore(p.score)}</td>
                    <td>{formatDate(p.row.created_at)}</td>
                  </tr>
                )),
              )}
            </tbody>
          </table>
        </div>
      </details>
    </figure>
  );
}

/* ───────────────────────── Delivery bar (checks / review mode) ───────────────────────── */

const SEGMENTS = [
  { key: "merged", label: "merged" },
  { key: "approved", label: "approved" },
  { key: "inReview", label: "in review" },
  { key: "inBranch", label: "in a branch" },
  { key: "open", label: "open" },
] as const;

/** "71% of 97 issues merged · 69 merged · 0 approved · …", drawn as one bar. */
export function DeliveryBar({ delivery, label }: { delivery: Delivery; label?: string }) {
  const total = Math.max(delivery.total, 1);
  const share = Math.round((delivery.merged / total) * 100);
  return (
    <div className="rp-delivery">
      <p className="rp-delivery-head">
        {label ? <strong>{label}: </strong> : null}
        <strong>{delivery.total === 0 ? "No issues yet" : `${share}% of ${delivery.total} issues merged`}</strong>
      </p>
      <div aria-hidden="true" className="rp-bar">
        {SEGMENTS.map((segment) =>
          delivery[segment.key] > 0 ? (
            <span
              className={`rp-bar-${segment.key}`}
              key={segment.key}
              style={{ flexGrow: delivery[segment.key] }}
            />
          ) : null,
        )}
      </div>
      <ul className="rp-bar-legend">
        {SEGMENTS.map((segment) => (
          <li key={segment.key}>
            <span aria-hidden="true" className={`rp-bar-key rp-bar-${segment.key}`} />
            {delivery[segment.key]} {segment.label}
          </li>
        ))}
      </ul>
    </div>
  );
}

import type { CSSProperties } from "react";

import { githubRefUrl } from "../_lib/github";
import { findTarget } from "../_lib/queries";
import type { MessageKind, SessionStatus, TrialOutcome } from "../_lib/types";

/** A target: its colour swatch, always beside its name. */
export function TargetChip({ id }: { id: string | null | undefined }) {
  if (!id) return <span className="rp-soft">—</span>;
  const target = findTarget(id);
  const style = { "--rp-target": target?.color ?? "var(--rp-ink-soft)" } as CSSProperties;
  return (
    <span className="rp-target" style={style}>
      <span aria-hidden="true" className="rp-target-swatch" />
      <span>{target?.name ?? id}</span>
    </span>
  );
}

/** GitHub picks black or white label text by the background's luminance. */
function labelText(hex: string): string {
  const clean = /^[0-9a-f]{6}$/i.test(hex) ? hex : "ededed";
  const channel = (offset: number) => {
    const c = parseInt(clean.slice(offset, offset + 2), 16) / 255;
    return c <= 0.03928 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4;
  };
  const luminance = 0.2126 * channel(0) + 0.7152 * channel(2) + 0.0722 * channel(4);
  return luminance > 0.179 ? "#1f2328" : "#ffffff";
}

/** A GitHub label, rendered the way GitHub renders it. */
export function LabelChip({ name, color }: { name: string; color: string }) {
  const hex = /^[0-9a-f]{6}$/i.test(color) ? color : "ededed";
  const style = { "--rp-chip-bg": `#${hex}`, "--rp-chip-fg": labelText(hex) } as CSSProperties;
  return (
    <span className="rp-chip" style={style}>
      {name}
    </span>
  );
}

const kindSymbol: Record<MessageKind, string> = {
  question: "?",
  proposal: "→",
  handoff: "⇄",
  answer: "✓",
  note: "·",
};

export function KindChip({ kind }: { kind: MessageKind }) {
  return (
    <span className={`rp-tag rp-kind-${kind}`}>
      <span aria-hidden="true">{kindSymbol[kind] ?? "·"}</span> {kind}
    </span>
  );
}

/** Pass / fail, as a symbol and a word. */
export function Verdict({ passed, labels }: { passed: boolean | null; labels?: [string, string] }) {
  const [yes, no] = labels ?? ["passed", "failed"];
  if (passed === null) return <span className="rp-tag">… pending</span>;
  return passed ? (
    <span className="rp-tag rp-pass">
      <span aria-hidden="true">✓</span> {yes}
    </span>
  ) : (
    <span className="rp-tag rp-fail">
      <span aria-hidden="true">✗</span> {no}
    </span>
  );
}

const statusSymbol: Record<SessionStatus, string> = { working: "●", ended: "■", abandoned: "○" };

export function StatusTag({ status }: { status: SessionStatus }) {
  return (
    <span className={`rp-tag rp-status-${status}`}>
      <span aria-hidden="true">{statusSymbol[status] ?? "·"}</span> {status}
    </span>
  );
}

export const outcomeSymbol: Record<TrialOutcome, string> = { gained: "▲", lost: "▼", neutral: "●" };

export function Outcome({ outcome, count }: { outcome: TrialOutcome; count?: number }) {
  return (
    <span className={`rp-tag rp-outcome-${outcome}`}>
      <span aria-hidden="true">{outcomeSymbol[outcome]}</span> {outcome}
      {count && count > 1 ? ` ×${count}` : ""}
    </span>
  );
}

/** An issue or PR number, linked to GitHub when the repo is known. */
export function Ref({ value, prefix = "#" }: { value: number | string | null | undefined; prefix?: string }) {
  if (value === null || value === undefined || value === "") return <span className="rp-soft">—</span>;
  const text = typeof value === "number" ? `${prefix}${value}` : value;
  const href = githubRefUrl(value);
  return href ? (
    <a className="rp-mono" href={href} rel="noreferrer" target="_blank">
      {text}
    </a>
  ) : (
    <span className="rp-mono">{text}</span>
  );
}

/** "#12 · PR #34", or a dash. */
export function IssuePr({ issue, pr }: { issue: number | null; pr: number | null }) {
  if (issue === null && pr === null) return <span className="rp-soft">—</span>;
  return (
    <span className="rp-refs">
      {issue !== null ? <Ref value={issue} /> : null}
      {pr !== null ? (
        <span>
          PR <Ref value={pr} />
        </span>
      ) : null}
    </span>
  );
}

"use client";

import Link from "next/link";
import { usePathname } from "next/navigation";
import { useEffect, useRef } from "react";

import type { SwarmNavItem, SwarmTarget } from "../_lib/config-types";
import { NavIcon, TargetMark } from "./icons";

function isCurrent(pathname: string, href: string): boolean {
  if (href === "/swarm") return pathname === "/swarm";
  return pathname === href || pathname.startsWith(`${href}/`);
}

/**
 * The swarm's navigation, grouped by section. Wide screens get a sticky
 * sidebar; narrow screens a disclosure menu that closes on navigation.
 */
export function SwarmNav({
  items,
  title,
  targets,
  targetsLabel,
}: {
  items: SwarmNavItem[];
  title: string;
  targets: SwarmTarget[];
  targetsLabel: string;
}) {
  const pathname = usePathname() ?? "/swarm";
  const menu = useRef<HTMLDetailsElement>(null);

  useEffect(() => {
    if (menu.current) menu.current.open = false;
  }, [pathname]);

  const sections: { name: string; items: SwarmNavItem[] }[] = [];
  for (const item of items) {
    const section = sections.find((entry) => entry.name === item.section);
    if (section) section.items.push(item);
    else sections.push({ name: item.section, items: [item] });
  }
  // The most specific match wins, so /swarm/targets/x names its target.
  const current =
    targets
      .map((target) => ({ href: `/swarm/targets/${encodeURIComponent(target.id)}`, label: target.name }))
      .find((entry) => isCurrent(pathname, entry.href)) ?? items.find((item) => isCurrent(pathname, item.href));

  const list = (
    <div className="rp-nav-sections">
      {sections.map((section) => (
        <div className="rp-nav-section" key={section.name}>
          <h2 className="rp-nav-heading">{section.name}</h2>
          <ul>
            {section.items.map((item) => (
              <li key={item.href}>
                <Link aria-current={isCurrent(pathname, item.href) ? "page" : undefined} href={item.href}>
                  <NavIcon item={item} />
                  <span>{item.label}</span>
                </Link>
              </li>
            ))}
          </ul>
        </div>
      ))}
      {targets.length > 0 ? (
        <div className="rp-nav-section rp-nav-targets">
          <h2 className="rp-nav-heading">{targetsLabel}</h2>
          <ul>
            {targets.map((target) => {
              const href = `/swarm/targets/${encodeURIComponent(target.id)}`;
              return (
                <li key={target.id}>
                  <Link aria-current={isCurrent(pathname, href) ? "page" : undefined} href={href}>
                    <TargetMark size="s" target={target} />
                    <span>{target.name}</span>
                  </Link>
                </li>
              );
            })}
          </ul>
        </div>
      ) : null}
    </div>
  );

  return (
    <>
      <nav aria-label={`${title} sections`} className="rp-nav-wide">
        {list}
      </nav>
      <details className="rp-nav-narrow" ref={menu}>
        <summary>
          <span className="rp-nav-burger" aria-hidden="true">
            <span />
            <span />
            <span />
          </span>
          <span>{current ? current.label : "Menu"}</span>
          <span className="rp-visually-hidden"> — open the section menu</span>
        </summary>
        <nav aria-label={`${title} sections`}>{list}</nav>
      </details>
    </>
  );
}

import Link from "next/link";

import { checksOf, formatDelta, formatDuration, formatScore, resultMode, word } from "../_lib/format";
import type { ResultRow } from "../_lib/types";
import { IssuePr, TargetChip, Verdict } from "./chips";
import { Empty, TimeAgo } from "./states";

/** What a referee run measured, in whichever mode it ran. Never assumes a score. */
export function ResultOutcome({ result }: { result: ResultRow }) {
  const mode = resultMode(result);
  if (mode === "score" && result.candidate_score !== null) {
    return (
      <span>
        {formatScore(result.candidate_score)}{" "}
        <span className="rp-soft">
          vs {formatScore(result.baseline_score)} ({formatDelta(result.delta)})
        </span>
      </span>
    );
  }
  const checks = checksOf(result);
  if (checks.length > 0) {
    const passed = checks.filter((check) => check.passed).length;
    return (
      <span>
        {passed}/{checks.length} checks passed
        {checks.some((check) => !check.passed) ? (
          <span className="rp-soft">
            {" "}
            · failed: {checks.filter((check) => !check.passed).map((check) => check.name).join(", ")}
          </span>
        ) : null}
      </span>
    );
  }
  if (mode === "review") return <span className="rp-soft">Gate is the reviewer&rsquo;s verdict</span>;
  return <span className="rp-soft">No measurements recorded</span>;
}

/** Named checks, each with a symbol and a word. */
export function ChecksList({ result }: { result: ResultRow }) {
  const checks = checksOf(result);
  if (checks.length === 0) return null;
  return (
    <ul className="rp-checks">
      {checks.map((check) => (
        <li key={check.name}>
          <Verdict passed={check.passed} />
          <code>{check.name}</code>
          <span className="rp-soft">
            {check.exitCode !== null && check.exitCode !== undefined ? `exit ${check.exitCode}` : ""}
            {check.durationMs !== null && check.durationMs !== undefined ? ` · ${formatDuration(check.durationMs)}` : ""}
          </span>
        </li>
      ))}
    </ul>
  );
}

export function ResultsTable({ results, showTarget = true }: { results: ResultRow[]; showTarget?: boolean }) {
  if (results.length === 0) {
    return (
      <Empty>
        No {word("results")} yet. Each <code>npx rallypoint swarm referee</code> run records one.
      </Empty>
    );
  }
  return (
    <table className="rp-table rp-reflow">
      <thead>
        <tr>
          <th scope="col">Run</th>
          <th scope="col">When</th>
          {showTarget ? <th scope="col">{word("target", true)}</th> : null}
          <th scope="col">Issue / PR</th>
          <th scope="col">Measured</th>
          <th scope="col">Verdict</th>
        </tr>
      </thead>
      <tbody>
        {results.map((result) => (
          <tr key={result.id}>
            <td data-label="Run">
              <Link className="rp-mono" href={`/swarm/results/${result.id}`}>
                #{result.id}
              </Link>
            </td>
            <td data-label="When">
              <TimeAgo at={result.created_at} />
            </td>
            {showTarget ? (
              <td data-label={word("target", true)}>
                <TargetChip id={result.target} />
              </td>
            ) : null}
            <td data-label="Issue / PR">
              <IssuePr issue={result.issue} pr={result.pr} />
            </td>
            <td data-label="Measured">
              <ResultOutcome result={result} />
            </td>
            <td data-label="Verdict">
              <Verdict passed={result.passed} />
            </td>
          </tr>
        ))}
      </tbody>
    </table>
  );
}

