/*
 * Rallypoint Swarm UI — scaffold styles.
 *
 * Everything is scoped under `.rp-swarm`, so this file never touches the rest
 * of your app. Retheme by overriding the variables below, either here, in
 * your own CSS (`.rp-swarm { --rp-accent: … }`), or per project through
 * `swarmConfig.theme.cssVars` in swarm.config.ts.
 *
 * Theming variables
 *   --rp-font-sans      Body text. Unset by default: Inter (self-hosted by
 *                       next/font in layout.tsx), then the system UI face.
 *                       Set it anywhere above .rp-swarm.
 *   --rp-font-display   Headings. Unset: Inter Tight, then --rp-font-sans.
 *   --rp-font-code      Code, refs and figures. Unset: JetBrains Mono, then
 *                       the system monospace.
 *   --rp-paper          Page ground and the light bands.
 *   --rp-paper-sunk     The frame (top bar, sidebar, hero) and alternate bands.
 *   --rp-ink            Text and the primary button.
 *   --rp-ink-soft       Secondary text (≥ 7:1 on paper).
 *   --rp-rule           Hairlines and table dividers.
 *   --rp-accent         Links and the current nav item.
 *   --rp-accent-fg      Text on the accent.
 *   --rp-focus          Focus ring.
 *   --rp-pass           "passed" / "kept" / "gained" text colour.
 *   --rp-fail           "failed" / "reverted" / "lost" text colour.
 *   --rp-live           The "working now" dot.
 *   --rp-sig-red, --rp-sig-yellow, --rp-sig-blue, --rp-sig-black, --rp-sig-white
 *                       The five signal inks used inside role flags.
 *   --rp-code-bg, --rp-code-fg
 *                       Code wells.
 *   --rp-radius-s, --rp-radius-m, --rp-radius-pill
 *                       Hairline (4px), panel (8px) and chip radii.
 *   --rp-sidebar        Sidebar width on wide screens.
 *   --rp-measure        Width of the content column inside a band.
 *
 * Target colours come from swarm.config.ts. Each target's colour is mixed
 * with the ink for text and with the paper for tiles, so any colour reads in
 * both themes.
 *
 * Dark mode follows `prefers-color-scheme`, unless the host sets
 * `data-theme="light"|"dark"` (or a `light` / `dark` class) on <html>, or
 * `data-theme` on the `.rp-swarm` element itself.
 */

.rp-swarm {
  --rp-sig-red: oklch(0.565 0.2 27.5);
  --rp-sig-yellow: oklch(0.85 0.165 89);
  --rp-sig-blue: oklch(0.45 0.175 263);
  --rp-sig-black: oklch(0.2 0.025 262);
  --rp-sig-white: oklch(0.995 0 0);
  --rp-flag-edge: oklch(0.2 0.01 85 / 0.9);
  --rp-paper: oklch(0.982 0.018 95);
  --rp-paper-sunk: oklch(0.948 0.042 95);
  --rp-ink: oklch(0.2 0.012 85);
  --rp-ink-soft: oklch(0.43 0.018 85);
  --rp-rule: oklch(0.86 0.03 92);
  --rp-accent: oklch(0.2 0.012 85);
  --rp-accent-fg: oklch(0.982 0.018 95);
  --rp-focus: oklch(0.55 0.2 263);
  --rp-pass: oklch(0.47 0.13 150);
  --rp-fail: oklch(0.5 0.19 27.5);
  --rp-live: oklch(0.6 0.16 150);
  --rp-code-bg: oklch(0.21 0.01 85);
  --rp-code-fg: oklch(0.95 0.03 92);
  --rp-radius-s: 4px;
  --rp-radius-m: 8px;
  --rp-radius-pill: 2em;
  --rp-sidebar: 224px;
  --rp-top: 52px;
  --rp-measure: 1140px;
  --rp-gutter: clamp(16px, 4vw, 40px);
  --rp-ease: cubic-bezier(0.16, 1, 0.3, 1);
  --rp-sans: var(--rp-font-sans, var(--rp-face-sans, Inter), ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif);
  --rp-display: var(--rp-font-display, var(--rp-face-display, "Inter Tight"), var(--rp-sans));
  --rp-mono: var(--rp-font-code, var(--rp-face-mono, "JetBrains Mono"), ui-monospace, SFMono-Regular, "SF Mono", "Cascadia Mono", Menlo, Consolas, monospace);

  background: var(--rp-paper);
  color: var(--rp-ink);
  color-scheme: light;
  display: grid;
  font-family: var(--rp-sans);
  font-size: 1rem;
  font-feature-settings: "ss01", "cv11";
  grid-template-areas:
    "top top"
    "side main";
  grid-template-columns: var(--rp-sidebar) minmax(0, 1fr);
  grid-template-rows: var(--rp-top) minmax(0, 1fr);
  line-height: 1.55;
  min-height: 100vh;
  min-height: 100dvh;
  -webkit-font-smoothing: antialiased;
}

/* Night variants: system preference unless the host chose light. */
@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]):not(.light) .rp-swarm:not([data-theme="light"]) {
    --rp-sig-yellow: oklch(0.84 0.16 88);
    --rp-sig-blue: oklch(0.47 0.17 263);
    --rp-flag-edge: oklch(0.12 0.005 85 / 0.9);
    --rp-paper: oklch(0.205 0.004 85);
    --rp-paper-sunk: oklch(0.175 0.004 85);
    --rp-ink: oklch(0.95 0.045 93);
    --rp-ink-soft: oklch(0.79 0.03 92);
    --rp-rule: oklch(0.32 0.008 85);
    --rp-accent: oklch(0.95 0.045 93);
    --rp-accent-fg: oklch(0.175 0.004 85);
    --rp-focus: oklch(0.8 0.13 250);
    --rp-pass: oklch(0.78 0.15 150);
    --rp-fail: oklch(0.74 0.15 27.5);
    --rp-live: oklch(0.78 0.16 150);
    --rp-code-bg: oklch(0.15 0.004 85);
    --rp-code-fg: oklch(0.95 0.045 93);
    color-scheme: dark;
  }
}

:root[data-theme="dark"] .rp-swarm:not([data-theme="light"]),
:root.dark .rp-swarm:not([data-theme="light"]),
.rp-swarm[data-theme="dark"] {
  --rp-sig-yellow: oklch(0.84 0.16 88);
  --rp-sig-blue: oklch(0.47 0.17 263);
  --rp-flag-edge: oklch(0.12 0.005 85 / 0.9);
  --rp-paper: oklch(0.205 0.004 85);
  --rp-paper-sunk: oklch(0.175 0.004 85);
  --rp-ink: oklch(0.95 0.045 93);
  --rp-ink-soft: oklch(0.79 0.03 92);
  --rp-rule: oklch(0.32 0.008 85);
  --rp-accent: oklch(0.95 0.045 93);
  --rp-accent-fg: oklch(0.175 0.004 85);
  --rp-focus: oklch(0.8 0.13 250);
  --rp-pass: oklch(0.78 0.15 150);
  --rp-fail: oklch(0.74 0.15 27.5);
  --rp-live: oklch(0.78 0.16 150);
  --rp-code-bg: oklch(0.15 0.004 85);
  --rp-code-fg: oklch(0.95 0.045 93);
  color-scheme: dark;
}

.rp-swarm *,
.rp-swarm *::before,
.rp-swarm *::after {
  box-sizing: border-box;
}

.rp-swarm {
  accent-color: var(--rp-ink);
  caret-color: var(--rp-ink);
  scrollbar-color: color-mix(in oklch, var(--rp-ink) 28%, transparent) transparent;
}

.rp-swarm ::selection {
  background: color-mix(in oklch, var(--rp-ink) 22%, transparent);
  color: inherit;
}

.rp-swarm table,
.rp-swarm time {
  font-variant-numeric: tabular-nums;
}

/* ───────────────────────── Base type ───────────────────────── */

.rp-swarm h1,
.rp-swarm h2,
.rp-swarm h3 {
  font-family: var(--rp-display);
  font-weight: 650;
  letter-spacing: -0.015em;
  margin: 0;
  overflow-wrap: anywhere;
  text-wrap: balance;
}

.rp-swarm h1 {
  font-size: clamp(2.25rem, 1.5rem + 2.8vw, 3.75rem);
  letter-spacing: -0.022em;
  line-height: 1.02;
}

.rp-swarm h2 {
  font-size: 1.5rem;
  line-height: 1.15;
}

.rp-swarm h3 {
  font-size: 1.125rem;
  letter-spacing: -0.015em;
  line-height: 1.25;
}

.rp-swarm p {
  margin: 0.5rem 0;
  max-width: 72ch;
  text-wrap: pretty;
}

.rp-swarm a {
  color: var(--rp-accent);
  text-decoration-color: color-mix(in oklch, currentColor 45%, transparent);
  text-decoration-thickness: 1px;
  text-underline-offset: 0.2em;
}

.rp-swarm a:hover {
  text-decoration-color: currentColor;
}

.rp-swarm :focus-visible {
  border-radius: 2px;
  outline: 2px solid var(--rp-focus);
  outline-offset: 2px;
}

.rp-swarm code,
.rp-swarm pre,
.rp-mono {
  font-family: var(--rp-mono);
  font-size: 0.875em;
  font-variant-ligatures: none;
}

.rp-swarm code {
  overflow-wrap: anywhere;
}

.rp-soft {
  color: var(--rp-ink-soft);
}

.rp-strong {
  font-size: 1.25rem;
  font-weight: 600;
}

.rp-break {
  overflow-wrap: anywhere;
}

.rp-visually-hidden {
  clip: rect(0 0 0 0);
  clip-path: inset(50%);
  height: 1px;
  overflow: hidden;
  position: absolute;
  white-space: nowrap;
  width: 1px;
}

.rp-skip {
  background: var(--rp-ink);
  color: var(--rp-paper) !important;
  left: 8px;
  padding: 8px 12px;
  position: absolute;
  top: -100px;
  z-index: 30;
}

.rp-skip:focus {
  top: 8px;
}

/* ───────────────────────── Frame and navigation ───────────────────────── */

.rp-top {
  align-items: center;
  background: var(--rp-paper-sunk);
  border-bottom: 1px solid var(--rp-rule);
  display: flex;
  gap: 16px;
  grid-area: top;
  height: var(--rp-top);
  justify-content: space-between;
  padding: 0 16px 0 20px;
  position: sticky;
  top: 0;
  z-index: 20;
}

.rp-brand {
  align-items: center;
  display: flex;
  font-weight: 650;
  gap: 10px;
  letter-spacing: -0.01em;
  min-width: 0;
}

.rp-brand a {
  color: var(--rp-ink);
  overflow: hidden;
  text-decoration: none;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.rp-top-end {
  align-items: center;
  display: flex;
  font-size: 0.8125rem;
  gap: 16px;
}

.rp-live {
  align-items: center;
  border: 1px solid var(--rp-rule);
  border-radius: var(--rp-radius-pill);
  color: var(--rp-ink-soft) !important;
  display: inline-flex;
  gap: 8px;
  min-height: 28px;
  padding: 0 10px;
  text-decoration: none;
  white-space: nowrap;
}

.rp-live-dot {
  background: currentColor;
  border-radius: 50%;
  display: inline-block;
  flex: none;
  height: 7px;
  opacity: 0.7;
  width: 7px;
}

.rp-live-on {
  color: var(--rp-ink) !important;
}

.rp-live-on .rp-live-dot {
  background: var(--rp-live);
  box-shadow: 0 0 0 0 color-mix(in oklch, var(--rp-live) 60%, transparent);
  opacity: 1;
}

@media (prefers-reduced-motion: no-preference) {
  .rp-live-on .rp-live-dot {
    animation: rp-pulse 2.4s var(--rp-ease) infinite;
  }
}

@keyframes rp-pulse {
  70% {
    box-shadow: 0 0 0 6px color-mix(in oklch, var(--rp-live) 0%, transparent);
  }
  100% {
    box-shadow: 0 0 0 0 color-mix(in oklch, var(--rp-live) 0%, transparent);
  }
}

.rp-sidebar {
  background: var(--rp-paper-sunk);
  border-right: 1px solid var(--rp-rule);
  grid-area: side;
}

.rp-sidebar-inner {
  display: flex;
  flex-direction: column;
  gap: 16px;
  height: calc(100vh - var(--rp-top));
  height: calc(100dvh - var(--rp-top));
  overflow-y: auto;
  padding: 18px 8px 24px;
  position: sticky;
  top: var(--rp-top);
}

.rp-nav-sections {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.rp-nav-heading {
  color: var(--rp-ink-soft);
  font-family: var(--rp-sans) !important;
  font-size: 0.6875rem !important;
  font-weight: 600 !important;
  letter-spacing: 0.08em !important;
  margin: 0 0 6px !important;
  padding: 0 10px;
  text-transform: uppercase;
}

.rp-nav-section ul {
  display: grid;
  gap: 1px;
  list-style: none;
  margin: 0;
  padding: 0;
}

.rp-nav-section a {
  align-items: center;
  border-radius: var(--rp-radius-m);
  color: var(--rp-ink);
  display: flex;
  font-size: 0.875rem;
  gap: 10px;
  min-height: 34px;
  padding: 4px 10px;
  text-decoration: none;
}

.rp-nav-section a .rp-icon {
  color: var(--rp-ink-soft);
  flex: none;
}

.rp-nav-section a:hover {
  background: color-mix(in oklch, var(--rp-ink) 6%, transparent);
}

.rp-nav-section a[aria-current="page"] {
  background: color-mix(in oklch, var(--rp-ink) 9%, transparent);
  font-weight: 600;
}

.rp-nav-section a[aria-current="page"] .rp-icon {
  color: var(--rp-ink);
}

.rp-nav-targets a {
  min-height: 38px;
}

.rp-nav-narrow {
  display: none;
}

.rp-session {
  margin: 0;
}

.rp-linkish {
  background: none;
  border: 0;
  color: var(--rp-accent);
  cursor: pointer;
  font: inherit;
  padding: 0;
  text-decoration: underline;
  text-decoration-color: color-mix(in oklch, currentColor 45%, transparent);
  text-underline-offset: 0.2em;
}

.rp-main {
  grid-area: main;
  min-width: 0;
  padding: 48px var(--rp-gutter) 112px;
  width: 100%;
}

.rp-main > * {
  margin-left: auto;
  margin-right: auto;
  max-width: var(--rp-measure);
}

/* The overview runs edge to edge: its bands carry their own gutters. */
.rp-main:has(> .rp-overview) {
  padding: 0;
}

.rp-main > .rp-overview {
  max-width: none;
}

@media (max-width: 899px) {
  .rp-swarm {
    display: block;
  }

  .rp-top {
    padding: 0 12px 0 16px;
  }

  .rp-sidebar {
    background: var(--rp-paper-sunk);
    border-bottom: 1px solid var(--rp-rule);
    border-right: 0;
    position: sticky;
    top: var(--rp-top);
    z-index: 15;
  }

  .rp-sidebar-inner {
    height: auto;
    overflow: visible;
    padding: 6px 12px;
    position: static;
  }

  .rp-nav-wide {
    display: none;
  }

  .rp-nav-narrow {
    display: block;
    position: static;
  }

  .rp-nav-narrow > summary {
    align-items: center;
    cursor: pointer;
    display: flex;
    font-size: 0.9375rem;
    font-weight: 600;
    gap: 10px;
    list-style: none;
    min-height: 44px;
    padding: 0 4px;
  }

  .rp-nav-narrow > summary::-webkit-details-marker {
    display: none;
  }

  .rp-nav-burger {
    display: inline-flex;
    flex-direction: column;
    gap: 3px;
  }

  .rp-nav-burger span {
    background: currentColor;
    display: block;
    height: 1.5px;
    width: 16px;
  }

  .rp-nav-narrow[open] > nav {
    background: var(--rp-paper-sunk);
    border-bottom: 1px solid var(--rp-rule);
    left: 0;
    max-height: calc(100dvh - var(--rp-top) - 57px);
    overflow-y: auto;
    padding: 8px 12px 20px;
    position: absolute;
    right: 0;
    top: 100%;
  }

  .rp-nav-narrow[open] .rp-nav-sections {
    display: grid;
    gap: 16px 8px;
    grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
  }

  .rp-main {
    padding-top: 32px;
  }
}

/* ───────────────────────── Page structure ───────────────────────── */

.rp-head {
  margin-bottom: 36px;
}

.rp-head h1 {
  font-size: clamp(2rem, 1.4rem + 2.2vw, 3.25rem);
}

.rp-lede {
  color: var(--rp-ink-soft);
  font-size: 1.1875rem;
  line-height: 1.5;
  margin-top: 14px !important;
  max-width: 60ch !important;
}

.rp-measure {
  color: var(--rp-ink-soft);
  font-size: 0.9375rem;
}

.rp-section {
  border-top: 1px solid var(--rp-rule);
  margin-top: 56px;
  padding-top: 28px;
}

.rp-section > h2 {
  font-size: clamp(1.5rem, 1.2rem + 1vw, 2rem);
  margin-bottom: 6px;
}

.rp-section-lede {
  color: var(--rp-ink-soft);
  margin-bottom: 20px !important;
}

.rp-stack {
  display: grid;
  gap: 20px;
  margin-top: 28px;
}

/* ───────────────────────── Figures and facts ───────────────────────── */

.rp-figures {
  border-bottom: 1px solid var(--rp-rule);
  border-top: 1px solid var(--rp-rule);
  display: grid;
  gap: 0;
  grid-template-columns: repeat(auto-fit, minmax(132px, 1fr));
  margin: 0 0 8px;
}

.rp-head + .rp-figures {
  border-top: 0;
  margin-top: -12px;
}

.rp-figures > div {
  padding: 16px 16px 16px 0;
}

.rp-figures dt {
  color: var(--rp-ink-soft);
  font-size: 0.8125rem;
  font-weight: 600;
}

.rp-figures dd {
  font-family: var(--rp-mono);
  font-size: 1.75rem;
  font-variant-numeric: tabular-nums;
  font-weight: 500;
  letter-spacing: -0.02em;
  line-height: 1.15;
  margin: 2px 0 0;
}

.rp-figures dd code {
  font-size: 1.125rem;
}

.rp-facts {
  display: grid;
  gap: 8px 24px;
  grid-template-columns: minmax(120px, max-content) minmax(0, 1fr);
  margin: 12px 0;
}

.rp-facts > div {
  display: contents;
}

.rp-facts dt {
  color: var(--rp-ink-soft);
  font-size: 0.875rem;
  font-weight: 600;
}

.rp-facts dd {
  margin: 0;
  min-width: 0;
}

@media (max-width: 599px) {
  .rp-facts {
    grid-template-columns: minmax(0, 1fr);
    gap: 2px;
  }

  .rp-facts dd {
    margin-bottom: 10px;
  }
}

/* ───────────────────────── Tables ───────────────────────── */

.rp-table {
  border-collapse: collapse;
  font-size: 0.9375rem;
  width: 100%;
}

.rp-table th,
.rp-table td {
  border-bottom: 1px solid var(--rp-rule);
  padding: 10px 12px 10px 0;
  text-align: left;
  vertical-align: top;
}

.rp-table thead th {
  border-bottom: 2px solid var(--rp-ink);
  color: var(--rp-ink-soft);
  font-size: 0.8125rem;
  font-weight: 600;
  white-space: nowrap;
}

.rp-table td {
  overflow-wrap: anywhere;
}

.rp-scroll {
  max-width: 100%;
  overflow-x: auto;
}

.rp-matrix th[scope="row"] {
  font-weight: 600;
  min-width: 160px;
}

.rp-matrix td {
  min-width: 140px;
}

.rp-cell {
  align-items: flex-start;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

/* Tables reflow into labelled blocks on narrow screens. */
@media (max-width: 767px) {
  .rp-reflow thead {
    display: none;
  }

  .rp-reflow,
  .rp-reflow tbody,
  .rp-reflow tr,
  .rp-reflow td {
    display: block;
    width: 100%;
  }

  .rp-reflow tr {
    border-bottom: 1px solid var(--rp-rule);
    padding: 12px 0;
  }

  .rp-reflow td {
    align-items: start;
    border: 0;
    display: grid;
    justify-items: start;
    gap: 12px;
    grid-template-columns: 7.5rem minmax(0, 1fr);
    padding: 3px 0;
  }

  .rp-reflow td::before {
    color: var(--rp-ink-soft);
    content: attr(data-label);
    font-size: 0.8125rem;
    font-weight: 600;
  }
}

/* ───────────────────────── Lists, feeds, cards ───────────────────────── */

.rp-plain {
  margin: 8px 0;
  padding-left: 1.2em;
}

.rp-list {
  list-style: none;
  margin: 0;
  padding: 0;
}

.rp-list > li {
  border-bottom: 1px solid var(--rp-rule);
  padding: 10px 0;
}

.rp-item-head {
  display: block;
}

.rp-item-meta {
  align-items: center;
  display: flex;
  flex-wrap: wrap;
  font-size: 0.875rem;
  gap: 6px 8px;
  margin-top: 6px;
}

.rp-feed {
  list-style: none;
  margin: 0;
  padding: 0;
}

.rp-feed > li {
  border-bottom: 1px solid var(--rp-rule);
  display: grid;
  gap: 4px 16px;
  grid-template-columns: 6.5rem minmax(0, 1fr);
  padding: 12px 0;
}

.rp-feed > li > time {
  color: var(--rp-ink-soft);
  font-size: 0.875rem;
}

@media (max-width: 599px) {
  .rp-feed > li {
    grid-template-columns: minmax(0, 1fr);
  }
}

.rp-cards {
  display: grid;
  gap: 16px;
  list-style: none;
  margin: 0;
  padding: 0;
}

.rp-cards > li {
  background: var(--rp-paper-sunk);
  border-radius: var(--rp-radius-m);
  min-width: 0;
  padding: 18px 20px;
}

.rp-cards h2 {
  font-size: 1.25rem;
  margin: 8px 0 4px;
}

.rp-card-meta {
  align-items: center;
  color: var(--rp-ink-soft);
  display: flex;
  flex-wrap: wrap;
  font-size: 0.875rem;
  gap: 6px 14px;
}

.rp-retro {
  border-top: 1px solid var(--rp-rule);
  padding-top: 12px;
}

.rp-notes {
  font-size: 0.9375rem;
  margin: 8px 0 0;
  padding-left: 1.2em;
}

.rp-notes time {
  color: var(--rp-ink-soft);
  font-size: 0.8125rem;
  margin-right: 6px;
}

.rp-details {
  margin-top: 12px;
}

.rp-details > summary {
  color: var(--rp-accent);
  cursor: pointer;
  font-size: 0.9375rem;
}

.rp-steps {
  margin: 0;
  max-width: 72ch;
  padding-left: 1.4em;
}

.rp-steps li {
  padding: 4px 0;
}

.rp-roles {
  counter-reset: rp-role;
  list-style: none;
  margin: 0;
  padding: 0;
}

.rp-roles > li {
  border-bottom: 1px solid var(--rp-rule);
  counter-increment: rp-role;
  display: grid;
  gap: 4px 20px;
  grid-template-columns: 2rem 9rem minmax(0, 1fr);
  padding: 10px 0;
}

.rp-roles > li::before {
  color: var(--rp-ink-soft);
  content: counter(rp-role) ".";
  font-variant-numeric: tabular-nums;
}

@media (max-width: 599px) {
  .rp-roles > li {
    grid-template-columns: 2rem minmax(0, 1fr);
  }

  .rp-roles > li > span:last-child {
    grid-column: 2;
  }
}

.rp-prompts {
  display: grid;
  gap: 20px;
  list-style: none;
  margin: 0;
  padding: 0;
}

.rp-prompts p {
  margin: 4px 0 8px;
}

.rp-threads {
  display: grid;
  gap: 20px;
  list-style: none;
  margin: 0;
  padding: 0;
}

.rp-threads > li {
  border-top: 1px solid var(--rp-rule);
  padding-top: 16px;
}

.rp-threads h2 {
  font-size: 1.125rem;
  margin-bottom: 8px;
}

.rp-message header {
  align-items: center;
  color: var(--rp-ink-soft);
  display: flex;
  flex-wrap: wrap;
  font-size: 0.875rem;
  gap: 6px 12px;
}

.rp-message p {
  margin: 6px 0 0;
  overflow-wrap: anywhere;
  white-space: pre-wrap;
}

.rp-replies {
  border-left: 2px solid var(--rp-rule);
  display: grid;
  gap: 14px;
  list-style: none;
  margin: 14px 0 0 6px;
  padding: 0 0 0 16px;
}

.rp-files li {
  padding: 6px 0;
}

.rp-files a[aria-current] {
  font-weight: 700;
}

/* ───────────────────────── Chips and tags ───────────────────────── */

.rp-flag {
  display: inline-block;
  flex: none;
  vertical-align: middle;
}

.rp-flag .sf-r { fill: var(--rp-sig-red); }
.rp-flag .sf-y { fill: var(--rp-sig-yellow); }
.rp-flag .sf-b { fill: var(--rp-sig-blue); }
.rp-flag .sf-k { fill: var(--rp-sig-black); }
.rp-flag .sf-w { fill: var(--rp-sig-white); }

.rp-flag .sf-edge {
  fill: none;
  stroke: var(--rp-flag-edge);
  stroke-width: 1;
}

.rp-role {
  align-items: center;
  display: inline-flex;
  gap: 8px;
  white-space: nowrap;
}

.rp-target {
  align-items: center;
  display: inline-flex;
  gap: 6px;
  white-space: nowrap;
}

.rp-target-swatch {
  background: var(--rp-target);
  border: 1px solid color-mix(in oklch, var(--rp-ink) 35%, transparent);
  border-radius: var(--rp-radius-s);
  display: inline-block;
  flex: none;
  height: 12px;
  width: 12px;
}

.rp-chip {
  background: var(--rp-chip-bg);
  border-radius: var(--rp-radius-pill);
  color: var(--rp-chip-fg);
  display: inline-block;
  font-family: var(--rp-sans);
  font-size: 0.75rem;
  font-weight: 600;
  line-height: 1;
  padding: 0.35em 0.7em 0.38em;
  white-space: nowrap;
}

.rp-tag {
  border: 1px solid var(--rp-rule);
  border-radius: var(--rp-radius-pill);
  display: inline-block;
  font-size: 0.8125rem;
  font-weight: 600;
  line-height: 1.2;
  padding: 0.15em 0.6em;
  white-space: nowrap;
}

.rp-pass,
.rp-outcome-gained {
  border-color: currentColor;
  color: var(--rp-pass);
}

.rp-fail,
.rp-outcome-lost {
  border-color: currentColor;
  color: var(--rp-fail);
}

.rp-status-working {
  border-color: var(--rp-sig-yellow);
}

.rp-kind-question { border-color: var(--rp-sig-yellow); }
.rp-kind-proposal { border-color: var(--rp-sig-blue); }
.rp-kind-handoff { border-color: var(--rp-sig-red); }
.rp-kind-answer { border-color: var(--rp-pass); }

.rp-refs {
  display: inline-flex;
  flex-wrap: wrap;
  gap: 0 8px;
}

.rp-checks {
  display: grid;
  gap: 6px;
  list-style: none;
  margin: 0;
  padding: 0;
}

.rp-checks li {
  align-items: center;
  display: flex;
  flex-wrap: wrap;
  gap: 6px 12px;
}

/* ───────────────────────── Filters ───────────────────────── */

.rp-filters {
  align-items: center;
  display: flex;
  flex-wrap: wrap;
  gap: 6px 12px;
  margin: 0 0 12px;
}

.rp-filters-label {
  color: var(--rp-ink-soft);
  font-size: 0.8125rem;
  font-weight: 600;
  min-width: 4.5rem;
}

.rp-filters ul {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  list-style: none;
  margin: 0;
  padding: 0;
}

.rp-filters a {
  border: 1px solid var(--rp-rule);
  border-radius: var(--rp-radius-s);
  color: var(--rp-ink);
  display: inline-block;
  font-size: 0.875rem;
  padding: 4px 10px;
  text-decoration: none;
}

.rp-filters a[aria-current="page"] {
  background: var(--rp-ink);
  border-color: var(--rp-ink);
  color: var(--rp-paper);
}

/* ───────────────────────── Panels, empty states, code ───────────────────────── */

.rp-panel {
  background: var(--rp-paper-sunk);
  border: 1px solid var(--rp-rule);
  border-radius: var(--rp-radius-m);
  margin: 0 0 24px;
  padding: 20px 22px;
}

.rp-panel-warn {
  background: color-mix(in oklch, var(--rp-sig-yellow) 12%, var(--rp-paper));
  border-color: color-mix(in oklch, var(--rp-sig-yellow) 55%, var(--rp-rule));
}

.rp-panel h2 {
  font-size: 1.375rem;
  margin-bottom: 8px;
}

.rp-empty {
  border: 1px dashed var(--rp-rule);
  border-radius: var(--rp-radius-m);
  color: var(--rp-ink-soft);
  margin: 8px 0 !important;
  max-width: none !important;
  padding: 18px 20px;
}

.rp-code,
.rp-file {
  background: var(--rp-code-bg);
  border-radius: var(--rp-radius-s);
  color: var(--rp-code-fg);
  font-size: 0.8125rem;
  line-height: 1.6;
  margin: 12px 0;
  max-width: 100%;
  overflow-x: auto;
  padding: 12px 16px;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}

.rp-code-nowrap {
  overflow-wrap: normal;
  white-space: pre;
}

.rp-file {
  max-height: 70vh;
  overflow-y: auto;
}

/* ───────────────────────── Buttons and forms ───────────────────────── */

.rp-button {
  align-items: center;
  background: var(--rp-ink);
  border: 1.5px solid var(--rp-ink);
  border-radius: var(--rp-radius-m);
  color: var(--rp-paper) !important;
  cursor: pointer;
  display: inline-flex;
  font: 600 0.9375rem/1 var(--rp-sans);
  min-height: 44px;
  padding: 0 22px;
  text-decoration: none !important;
}

.rp-button-quiet {
  background: transparent;
  border-color: currentColor;
  color: var(--rp-ink) !important;
}

.rp-forms {
  display: grid;
  gap: 24px;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 300px), 1fr));
  max-width: 760px;
}

.rp-form {
  background: var(--rp-paper-sunk);
  border-radius: var(--rp-radius-m);
  display: grid;
  gap: 14px;
  padding: 20px;
}

.rp-form h2 {
  font-size: 1.25rem;
}

.rp-form label {
  display: grid;
  font-size: 0.875rem;
  font-weight: 600;
  gap: 6px;
}

.rp-form input {
  background: var(--rp-paper);
  border: 1.5px solid var(--rp-rule);
  border-radius: var(--rp-radius-s);
  color: var(--rp-ink);
  font: 400 1rem var(--rp-sans);
  min-height: 44px;
  padding: 0 12px;
  width: 100%;
}

.rp-form .rp-button {
  justify-self: start;
}

/* ───────────────────────── Charts ───────────────────────── */

.rp-chart {
  margin: 0;
}

.rp-legend {
  display: flex;
  flex-wrap: wrap;
  font-size: 0.875rem;
  gap: 6px 18px;
  list-style: none;
  margin: 0 0 8px;
  padding: 0;
}

.rp-legend li {
  align-items: center;
  display: inline-flex;
  gap: 6px;
}

.rp-legend-marker {
  fill: color-mix(in oklch, var(--rp-series) 78%, var(--rp-ink));
}

.rp-plot {
  display: block;
  height: auto;
  overflow: visible;
  width: 100%;
}

.rp-plot-narrow {
  display: none;
}

@media (max-width: 599px) {
  .rp-plot-wide {
    display: none;
  }

  .rp-plot-narrow {
    display: block;
  }
}

.rp-plot-grid line {
  stroke: var(--rp-rule);
  stroke-width: 1;
}

.rp-plot-grid text,
.rp-plot-label {
  fill: var(--rp-ink-soft);
  font-family: var(--rp-sans);
  font-size: 12px;
}

.rp-plot-label {
  fill: var(--rp-ink);
  font-weight: 600;
}

.rp-plot-series {
  /* Pulled toward the ink so any target colour holds up on either ground. */
  --rp-series-ink: color-mix(in oklch, var(--rp-series) 78%, var(--rp-ink));
}

.rp-plot-series path:first-child {
  fill: none;
  stroke: var(--rp-series-ink);
  stroke-linejoin: round;
  stroke-width: 2.5;
}

.rp-plot-series circle,
.rp-plot-series rect,
.rp-plot-series path:not(:first-child) {
  fill: var(--rp-series-ink);
  stroke: var(--rp-paper);
  stroke-width: 1.5;
}

.rp-delivery-head {
  margin: 0 0 8px !important;
}

.rp-bar {
  background: var(--rp-paper-sunk);
  border: 1px solid var(--rp-rule);
  border-radius: var(--rp-radius-s);
  display: flex;
  height: 18px;
  overflow: hidden;
}

.rp-bar > span {
  flex-basis: 0;
  min-width: 2px;
}

.rp-bar-merged { background: var(--rp-ink); }
.rp-bar-approved { background: var(--rp-pass); }
.rp-bar-inReview { background: var(--rp-sig-blue); }
.rp-bar-inBranch { background: var(--rp-sig-yellow); }
.rp-bar-open {
  background: repeating-linear-gradient(
    135deg,
    var(--rp-rule) 0 3px,
    transparent 3px 7px
  );
}

.rp-bar-legend {
  display: flex;
  flex-wrap: wrap;
  font-size: 0.875rem;
  gap: 4px 16px;
  list-style: none;
  margin: 8px 0 0;
  padding: 0;
}

.rp-bar-legend li {
  align-items: center;
  display: inline-flex;
  gap: 6px;
}

.rp-bar-key {
  border: 1px solid var(--rp-rule);
  display: inline-block;
  height: 10px;
  width: 10px;
}

@media (prefers-reduced-motion: reduce) {
  .rp-swarm *,
  .rp-swarm *::before,
  .rp-swarm *::after {
    scroll-behavior: auto !important;
    transition: none !important;
    animation: none !important;
  }
}

/* ───────────────────────── Overview: latest strip and hero ───────────────────────── */

.rp-overview {
  display: flex;
  flex-direction: column;
}

.rp-justin {
  align-items: center;
  background: var(--rp-paper);
  border-bottom: 1px solid var(--rp-rule);
  display: flex;
  font-size: 0.8125rem;
  gap: 6px 14px;
  margin: 0 !important;
  max-width: none !important;
  min-height: 42px;
  padding: 8px var(--rp-gutter);
}

.rp-justin-label {
  align-items: center;
  display: inline-flex;
  flex: none;
  font-weight: 600;
  gap: 8px;
}

.rp-justin-label .rp-live-dot {
  background: var(--rp-live);
  opacity: 1;
}

.rp-justin-text {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.rp-justin-time {
  color: var(--rp-ink-soft);
  flex: none;
  font-family: var(--rp-mono);
  font-size: 0.75rem;
}

.rp-justin .rp-next {
  flex: none;
  margin-left: auto;
}

.rp-hero {
  background: var(--rp-paper-sunk);
  border-bottom: 1px solid var(--rp-rule);
  isolation: isolate;
  overflow: hidden;
  padding: clamp(64px, 11vw, 176px) var(--rp-gutter) clamp(56px, 9vw, 152px);
  position: relative;
}

.rp-hero-inner {
  margin: 0 auto;
  max-width: var(--rp-measure);
  position: relative;
  z-index: 1;
}

.rp-hero-note {
  color: var(--rp-ink-soft);
  font-size: 0.875rem;
  margin: 14px 0 0 !important;
}

.rp-hero-note code {
  font-size: 0.8125rem;
}

.rp-hero h1 {
  font-size: clamp(2.5rem, 1.2rem + 4.6vw, 4.5rem);
  letter-spacing: -0.022em;
  line-height: 1.02;
  max-width: 17ch;
}

.rp-hero-lede {
  color: var(--rp-ink-soft);
  font-size: clamp(1.0625rem, 1rem + 0.3vw, 1.25rem);
  line-height: 1.5;
  margin-top: 28px !important;
  max-width: 52ch !important;
}

.rp-actions {
  align-items: center;
  display: flex;
  flex-wrap: wrap;
  gap: 12px 28px;
  margin-top: 40px;
}

.rp-button-hero {
  font-size: 1rem;
  min-height: 46px;
  padding: 0 22px;
}

.rp-next {
  align-items: center;
  color: var(--rp-ink) !important;
  display: inline-flex;
  font-weight: 500;
  gap: 6px;
  text-decoration: none !important;
}

.rp-actions .rp-next {
  font-size: 1rem;
}

.rp-next .rp-arrow {
  flex: none;
  transition: transform 200ms var(--rp-ease);
}

.rp-next:hover .rp-arrow {
  transform: translateX(3px);
}

.rp-next:hover {
  text-decoration: underline !important;
  text-decoration-color: color-mix(in oklch, currentColor 45%, transparent) !important;
  text-underline-offset: 0.22em;
}

/* Receding planes in each target's colour: a nod to the record being kept. */
.rp-hero-backdrop {
  inset: 0;
  mask-image: linear-gradient(90deg, transparent 40%, #000 85%);
  -webkit-mask-image: linear-gradient(90deg, transparent 40%, #000 85%);
  perspective: 900px;
  pointer-events: none;
  position: absolute;
  z-index: 0;
}

.rp-plane {
  --rp-plane-line: color-mix(in oklch, var(--rp-target) 38%, transparent);
  background-image:
    linear-gradient(var(--rp-plane-line) 1px, transparent 1px),
    linear-gradient(90deg, var(--rp-plane-line) 1px, transparent 1px);
  background-size: 32px 32px;
  border: 1px solid var(--rp-plane-line);
  display: block;
  position: absolute;
  transform: rotateX(60deg) rotateZ(-32deg);
  transform-origin: center;
}

.rp-plane-1 {
  height: 420px;
  right: -60px;
  top: 34%;
  width: 640px;
}

.rp-plane-2 {
  height: 240px;
  opacity: 0.8;
  right: 18%;
  top: 4%;
  width: 380px;
}

.rp-plane-3 {
  height: 260px;
  opacity: 0.7;
  right: -180px;
  top: 0;
  width: 420px;
}

@media (max-width: 899px) {
  .rp-hero-backdrop {
    opacity: 0.55;
  }

  .rp-justin {
    flex-wrap: wrap;
  }

  .rp-justin-text {
    flex-basis: 100%;
    order: 3;
    white-space: normal;
  }

  .rp-justin .rp-next {
    margin-left: auto;
  }
}

/* ───────────────────────── Bands ───────────────────────── */

.rp-band {
  background: var(--rp-paper);
  border-bottom: 1px solid var(--rp-rule);
  padding: clamp(56px, 8vw, 112px) var(--rp-gutter);
}

.rp-band-sunk {
  background: color-mix(in oklch, var(--rp-paper-sunk) 55%, var(--rp-paper));
}

.rp-band-inner {
  margin: 0 auto;
  max-width: var(--rp-measure);
}

.rp-band-title {
  font-size: clamp(2rem, 1.3rem + 2.6vw, 3.25rem) !important;
  letter-spacing: -0.02em !important;
  line-height: 1.04 !important;
}

.rp-band-lede {
  color: var(--rp-ink-soft);
  font-size: 1.0625rem;
  margin-top: 20px !important;
  max-width: 60ch !important;
}

.rp-band-action {
  margin: 16px 0 0 !important;
}

.rp-band-inner > :is(.rp-tcards, .rp-chart, .rp-now, .rp-steps-list, .rp-table, .rp-scroll, .rp-empty, .rp-panel, .rp-bar, .rp-stack) {
  margin-top: 44px;
}

.rp-band-inner > .rp-stack {
  margin-top: 28px;
}

/* ───────────────────────── Right now ───────────────────────── */

.rp-now {
  display: grid;
  gap: 40px 64px;
  grid-template-columns: minmax(0, 1.25fr) minmax(0, 1fr);
}

.rp-now-main {
  display: grid;
  gap: 14px;
  justify-items: start;
}

.rp-now-status {
  font-family: var(--rp-display);
  font-size: clamp(1.375rem, 1.1rem + 0.9vw, 1.875rem);
  font-weight: 550;
  letter-spacing: -0.012em;
  line-height: 1.2;
  margin: 0 !important;
}

.rp-now-list {
  display: grid;
  gap: 12px;
  list-style: none;
  margin: 6px 0 8px;
  padding: 0;
  width: 100%;
}

.rp-now-list li {
  align-items: start;
  display: grid;
  gap: 4px 14px;
  grid-template-columns: max-content minmax(0, 1fr) max-content;
}

.rp-now-what {
  min-width: 0;
}

.rp-now-who {
  color: var(--rp-ink-soft);
  display: flex;
  flex-wrap: wrap;
  font-size: 0.8125rem;
  gap: 2px 12px;
  margin-top: 2px;
}

.rp-now-side {
  border-left: 1px solid var(--rp-rule);
  display: grid;
  gap: 10px;
  justify-items: start;
  padding-left: 40px;
}

.rp-now-meta {
  color: var(--rp-ink-soft);
  font-size: 0.875rem;
  margin: 0 !important;
}

.rp-now-latest {
  font-size: 1.1875rem;
  line-height: 1.5;
  margin: 0 0 6px !important;
}

@media (max-width: 799px) {
  .rp-now {
    grid-template-columns: minmax(0, 1fr);
  }

  .rp-now-side {
    border-left: 0;
    border-top: 1px solid var(--rp-rule);
    padding: 28px 0 0;
  }

  .rp-now-list li {
    grid-template-columns: max-content minmax(0, 1fr);
  }

  .rp-now-list li > .rp-target {
    grid-column: 2;
  }
}

/* ───────────────────────── Target marks and cards ───────────────────────── */

.rp-mark {
  --rp-target-ink: color-mix(in oklch, var(--rp-target) 72%, var(--rp-ink));
  align-items: center;
  background: color-mix(in oklch, var(--rp-target) 16%, var(--rp-paper));
  border: 1px solid color-mix(in oklch, var(--rp-target) 42%, var(--rp-rule));
  border-radius: 6px;
  color: var(--rp-target-ink);
  display: inline-flex;
  flex: none;
  font-family: var(--rp-display);
  font-weight: 700;
  justify-content: center;
  line-height: 1;
}

.rp-mark-s {
  font-size: 0.6875rem;
  height: 22px;
  width: 22px;
}

.rp-mark-m {
  font-size: 0.9375rem;
  height: 32px;
  width: 32px;
}

.rp-mark-l {
  border-radius: 10px;
  font-size: 1.375rem;
  height: 48px;
  width: 48px;
}

.rp-tcards {
  display: grid;
  gap: 0 64px;
  grid-template-columns: repeat(auto-fill, minmax(min(100%, 420px), 1fr));
}

.rp-tcard {
  border-top: 1px solid var(--rp-rule);
  display: grid;
  gap: 24px;
  grid-template-rows: auto auto 1fr;
  padding: 32px 0 48px;
  position: relative;
}

.rp-tcard-head {
  align-items: center;
  display: grid;
  gap: 16px;
  grid-template-columns: max-content minmax(0, 1fr) max-content;
}

.rp-tcard-head .rp-arrow {
  color: var(--rp-ink-soft);
  height: 18px;
  transition: transform 200ms var(--rp-ease), color 200ms var(--rp-ease);
  width: 18px;
}

.rp-tcard:hover .rp-tcard-head .rp-arrow {
  color: var(--rp-ink);
  transform: translateX(3px);
}

.rp-tcard-name {
  font-size: clamp(1.375rem, 1.2rem + 0.6vw, 1.75rem) !important;
  letter-spacing: -0.015em !important;
}

.rp-tcard-name a {
  color: var(--rp-ink);
  text-decoration: none;
}

/* The whole card is one link, via the heading's link. */
.rp-cover::after {
  content: "";
  inset: 0;
  position: absolute;
}

.rp-tcard:has(.rp-cover:focus-visible) {
  outline: 2px solid var(--rp-focus);
  outline-offset: 4px;
}

.rp-tcard .rp-cover:focus-visible {
  outline: none;
}

.rp-tcard-desc {
  color: var(--rp-ink-soft);
  font-size: 0.875rem;
  margin: 2px 0 0 !important;
}

.rp-tcard-figs {
  align-items: end;
  display: flex;
  flex-wrap: wrap;
  gap: 16px 48px;
  margin: 0;
}

.rp-tcard-figs dt {
  color: var(--rp-ink-soft);
  font-size: 0.8125rem;
  margin-bottom: 6px;
}

.rp-tcard-figs dd {
  margin: 0;
}

.rp-big {
  font-family: var(--rp-mono);
  font-size: clamp(2.75rem, 2rem + 2.6vw, 4rem);
  font-variant-numeric: tabular-nums;
  font-weight: 500;
  letter-spacing: -0.04em;
  line-height: 0.95;
}

.rp-unit {
  color: var(--rp-ink-soft);
  font-family: var(--rp-sans);
  font-size: 1rem;
  font-weight: 500;
  letter-spacing: 0;
  margin-left: 8px;
}

.rp-mid {
  font-family: var(--rp-mono);
  font-size: 1.625rem;
  font-weight: 400;
  letter-spacing: -0.02em;
  line-height: 1;
}

.rp-tcard-next {
  color: var(--rp-ink);
  font-size: 0.9375rem;
  margin: 0 !important;
}

/* ───────────────────────── Steps ───────────────────────── */

.rp-steps-list {
  counter-reset: none;
  display: grid;
  gap: 0 64px;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 420px), 1fr));
  list-style: none;
  margin: 0;
  padding: 0;
}

.rp-steps-list > li {
  border-top: 1px solid var(--rp-rule);
  display: grid;
  gap: 20px;
  grid-template-columns: 40px minmax(0, 1fr);
  padding: 24px 0 32px;
}

.rp-step-n {
  color: var(--rp-ink-soft);
  font-family: var(--rp-mono);
  font-size: 0.875rem;
  padding-top: 3px;
}

.rp-steps-list h3 {
  font-size: 1.1875rem;
}

.rp-steps-list p {
  color: var(--rp-ink-soft);
  margin: 6px 0 0 !important;
}

/* ───────────────────────── Target page head ───────────────────────── */

.rp-target-title {
  align-items: center;
  display: flex;
  gap: 18px;
}

.rp-target-figs {
  border-bottom: 1px solid var(--rp-rule);
  border-top: 1px solid var(--rp-rule);
  margin-top: 32px;
  padding: 24px 0;
}

.rp-target-head + .rp-section,
.rp-target-head + .rp-panel + .rp-section {
  border-top: 0;
  margin-top: 16px;
}

import type { Metadata } from "next";
import Link from "next/link";
import { notFound } from "next/navigation";

import { DeliveryBar, ScoreChart } from "../../_components/charts";
import { IssuePr, LabelChip, Ref } from "../../_components/chips";
import { ResultsTable } from "../../_components/results";
import { TargetMark, targetStyle } from "../../_components/icons";
import { Empty, Gate, Panel, QueryErrors, Section, TimeAgo } from "../../_components/states";
import { cap, formatNumber, formatScore, word } from "../../_lib/format";
import { swarmConfig } from "../../swarm.config";
import { findTarget, getSwarmContext, getTarget, measureMode } from "../../_lib/queries";

export const dynamic = "force-dynamic";

type Props = { params: Promise<{ id: string }> };

export async function generateMetadata({ params }: Props): Promise<Metadata> {
  const { id } = await params;
  return { title: findTarget(decodeURIComponent(id))?.name ?? decodeURIComponent(id) };
}

export default async function TargetPage({ params }: Props) {
  const { id: raw } = await params;
  const id = decodeURIComponent(raw);
  const context = await getSwarmContext();
  if (context.state !== "ok") return <Gate context={context} />;
  const data = await getTarget(id);
  if (!data) notFound();
  const mode = measureMode(context.settings);

  return (
    <>
      <header className="rp-head rp-target-head" style={targetStyle(data.target)}>
        <div className="rp-target-title">
          <TargetMark size="l" target={data.target} />
          <h1>{data.target.name}</h1>
        </div>
        {data.target.description ? <p className="rp-lede">{data.target.description}</p> : null}
        <p className="rp-measure">
          Issues for this {word("target")} carry the label <code>target:{data.target.id}</code>.{" "}
          <Link href="/swarm/targets">All {word("targets")}</Link>
        </p>
        <dl className="rp-tcard-figs rp-target-figs">
          {mode === "score" ? (
            <div>
              <dt>{swarmConfig.measure.label || cap(word("score"))}</dt>
              <dd className="rp-big">
                {formatNumber(data.versions[0]?.score ?? null)}
                {swarmConfig.measure.unit && data.versions[0]?.score != null ? (
                  <span className="rp-unit">{swarmConfig.measure.unit}</span>
                ) : null}
              </dd>
            </div>
          ) : null}
          <div>
            <dt>{cap(word("version"))}</dt>
            <dd className="rp-mid">{data.versions[0]?.version ?? "—"}</dd>
          </div>
          <div>
            <dt>{cap(word("results"))} passed</dt>
            <dd className="rp-mid">
              {formatNumber(data.results.filter((row) => row.passed).length)}
              <span className="rp-unit">of {formatNumber(data.results.length)}</span>
            </dd>
          </div>
          <div>
            <dt>{cap(word("buried"))}</dt>
            <dd className="rp-mid">{formatNumber(data.buried.length)}</dd>
          </div>
        </dl>
      </header>
      <QueryErrors errors={data.errors} />

      {mode === "score" ? (
        <Section title={`${swarmConfig.measure.label || cap(word("score"))} over time`}>
          {data.versions.some((row) => row.score !== null) ? (
            <ScoreChart label={`${data.target.name} ${word("score")}`} targets={[data.target]} versions={data.versions} />
          ) : (
            <Empty>
              Nothing {word("shipped")} with a {word("score")} yet. The first point appears when the merger runs{" "}
              <code>npx rallypoint swarm ship --target {data.target.id} --score &lt;n&gt;</code>.
            </Empty>
          )}
        </Section>
      ) : (
        <Section title="Delivery">
          {data.delivery && data.delivery.total > 0 ? (
            <DeliveryBar delivery={data.delivery} />
          ) : !data.github.ok ? (
            <Panel title="GitHub is not connected" tone="warn">
              <p>
                Delivery is counted from issues labelled <code>target:{data.target.id}</code>. {data.github.message}
              </p>
            </Panel>
          ) : (
            <Empty>
              No issues for this {word("target")} yet. Open some with <code>npx rallypoint swarm plan plan.json</code>,
              giving each task <code>&quot;target&quot;: &quot;{data.target.id}&quot;</code>.
            </Empty>
          )}
        </Section>
      )}

      <Section title={`${cap(word("versions"))} ${word("shipped")}`}>
        {data.versions.length === 0 ? (
          <Empty>
            None yet. A merger records each one with <code>npx rallypoint swarm ship --target {data.target.id}</code>.
          </Empty>
        ) : (
          <ul className="rp-list">
            {data.versions.map((row) => (
              <li key={row.id}>
                <span className="rp-mono">{row.version}</span>
                {row.score !== null ? <> · {formatScore(row.score)}</> : null} · PR <Ref value={row.pr} /> ·{" "}
                <TimeAgo at={row.created_at} />
                {row.notes ? <p className="rp-soft">{row.notes}</p> : null}
              </li>
            ))}
          </ul>
        )}
      </Section>

      <Section title={cap(word("results"))}>
        <ResultsTable results={data.results} showTarget={false} />
      </Section>

      <Section title={`${cap(word("ideas"))} ${word("buried")}`}>
        {data.buried.length === 0 ? (
          <Empty>
            None yet. An {word("idea")} that loses its referee run is recorded with{" "}
            <code>npx rallypoint swarm bury</code>.
          </Empty>
        ) : (
          <ul className="rp-list">
            {data.buried.map((row) => (
              <li key={row.id}>
                <strong>{row.idea}</strong> <IssuePr issue={row.issue} pr={row.pr} />
                {row.lesson ? <p>{row.lesson}</p> : null}
              </li>
            ))}
          </ul>
        )}
      </Section>

      <Section title="Open issues">
        {!data.github.ok ? (
          <Empty>Open issues are read from GitHub. {data.github.message}</Empty>
        ) : data.openIssues.length === 0 ? (
          <Empty>
            No open issues with the <code>target:{data.target.id}</code> label. Plan more with{" "}
            <code>npx rallypoint swarm plan plan.json</code>.
          </Empty>
        ) : (
          <ul className="rp-list">
            {data.openIssues.map((item) => (
              <li key={item.number}>
                <Ref value={item.number} /> {item.title}{" "}
                {item.labels
                  .filter((label) => !label.name.startsWith("target:"))
                  .map((label) => (
                    <LabelChip color={label.color} key={label.name} name={label.name} />
                  ))}
              </li>
            ))}
          </ul>
        )}
      </Section>
    </>
  );
}

import type { Metadata } from "next";

import { TargetCard } from "../_components/bands";
import { Empty, Gate, PageHead, QueryErrors } from "../_components/states";
import { cap, word } from "../_lib/format";
import { getSwarmContext, getTargets } from "../_lib/queries";
import { swarmConfig } from "../swarm.config";

export const metadata: Metadata = { title: cap(word("targets")) };
export const dynamic = "force-dynamic";

export default async function TargetsPage() {
  const context = await getSwarmContext();
  if (context.state !== "ok") return <Gate context={context} />;
  const { targets, errors } = await getTargets();
  const score = swarmConfig.measure.mode === "score";

  return (
    <>
      <PageHead
        title={cap(word("targets"))}
        lede={`The parts of the goal the swarm works on, side by side. ${
          score
            ? `Each ${swarmConfig.measure.label || word("score")} is the latest ${word("version")} ${word("shipped")}, measured by the referee.`
            : `Each counts the ${word("versions")} ${word("shipped")} after passing the gate.`
        } Issues carry a target:<id> label.`}
      />
      <QueryErrors errors={errors} />
      {targets.length === 0 ? (
        <Empty>
          No {word("targets")} yet. Add them to <code>targets</code> in <code>.rallypoint/swarm.json</code>, run{" "}
          <code>npx rallypoint swarm init</code> to create their labels, then add each one to{" "}
          <code>swarm.config.ts</code> (or regenerate it with <code>npx rallypoint swarm ui-config --force</code>).
        </Empty>
      ) : (
        <div className="rp-tcards">
          {targets.map((entry) => (
            <TargetCard entry={entry} headingLevel={2} key={entry.target.id} />
          ))}
        </div>
      )}
    </>
  );
}

import type { Metadata } from "next";

import { Ref, TargetChip } from "../_components/chips";
import { Empty, Gate, PageHead, QueryErrors } from "../_components/states";
import { TimeAgo } from "../_components/states";
import { cap, formatScore, shortSha, word } from "../_lib/format";
import { getSwarmContext, getVersions } from "../_lib/queries";

export const metadata: Metadata = { title: cap(word("versions")) };
export const dynamic = "force-dynamic";

export default async function VersionsPage() {
  const context = await getSwarmContext();
  if (context.state !== "ok") return <Gate context={context} />;
  const { versions, errors } = await getVersions();
  const anyScore = versions.some((row) => row.score !== null);

  return (
    <>
      <PageHead
        title={cap(word("versions"))}
        lede={`Every ${word("version")} ${word("shipped")}: recorded by the merger after the pull request merged.`}
      />
      <QueryErrors errors={errors} />
      {versions.length === 0 ? (
        <Empty>
          Nothing {word("shipped")} yet. The merger records a {word("version")} with{" "}
          <code>npx rallypoint swarm ship</code>.
        </Empty>
      ) : (
        <table className="rp-table rp-reflow">
          <thead>
            <tr>
              <th scope="col">{cap(word("version"))}</th>
              <th scope="col">{cap(word("target"))}</th>
              {anyScore ? <th scope="col">{cap(word("score"))}</th> : null}
              <th scope="col">PR</th>
              <th scope="col">Commit</th>
              <th scope="col">When</th>
              <th scope="col">Notes</th>
            </tr>
          </thead>
          <tbody>
            {versions.map((row) => (
              <tr key={row.id}>
                <td className="rp-mono" data-label={cap(word("version"))}>
                  {row.version}
                </td>
                <td data-label={cap(word("target"))}>
                  <TargetChip id={row.target} />
                </td>
                {anyScore ? <td data-label={cap(word("score"))}>{formatScore(row.score)}</td> : null}
                <td data-label="PR">
                  <Ref value={row.pr} />
                </td>
                <td className="rp-mono" data-label="Commit">
                  {shortSha(row.commit_sha)}
                </td>
                <td data-label="When">
                  <TimeAgo at={row.created_at} />
                </td>
                <td data-label="Notes">{row.notes ?? <span className="rp-soft">—</span>}</td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </>
  );
}
